function exportDXF(){
if(!walls.length&&!rooms.length){alert('Сначала добавь стены или помещения.');return}
const out=['0','SECTION','2','HEADER','9','$ACADVER','1','AC1015','9','$INSUNITS','70','4','0','ENDSEC','0','SECTION','2','TABLES','0','TABLE','2','LAYER','70','5'];
[['WALLS',7],['OPENINGS',4],['ROOMS',3],['DIMENSIONS',2],['FURNITURE',6]].forEach(([name,color])=>out.push('0','LAYER','2',name,'70','0','62',String(color),'6','CONTINUOUS'));
out.push('0','ENDTAB','0','ENDSEC','0','SECTION','2','ENTITIES');
const mm=v=>Number(v||0)*1000,fmt=v=>Number(v).toFixed(3);
const line=(a,b,layer)=>out.push('0','LINE','8',layer,'10',fmt(mm(a.x)),'20',fmt(mm(a.y)),'30','0','11',fmt(mm(b.x)),'21',fmt(mm(b.y)),'31','0');
const textEntity=(p,value,height=180,layer='DIMENSIONS')=>{const safe=String(value).replace(/[\r\n]/g,' ').replace(/[<>]/g,'');out.push('0','TEXT','8',layer,'10',fmt(mm(p.x)),'20',fmt(mm(p.y)),'30','0','40',String(height),'1',safe)};
walls.forEach(w=>{const dx=w.b.x-w.a.x,dy=w.b.y-w.a.y,L=Math.hypot(dx,dy)||1,t=(w.thickness||200)/2000,nx=-dy/L*t,ny=dx/L*t;line({x:w.a.x+nx,y:w.a.y+ny},{x:w.b.x+nx,y:w.b.y+ny},'WALLS');line({x:w.a.x-nx,y:w.a.y-ny},{x:w.b.x-nx,y:w.b.y-ny},'WALLS');line({x:w.a.x+nx,y:w.a.y+ny},{x:w.a.x-nx,y:w.a.y-ny},'WALLS');line({x:w.b.x+nx,y:w.b.y+ny},{x:w.b.x-nx,y:w.b.y-ny},'WALLS');});
openings.forEach(o=>{const w=walls.find(x=>x.id===o.wallId);if(!w)return;const L=len(w)||1,ux=(w.b.x-w.a.x)/L,uy=(w.b.y-w.a.y)/L,cx=w.a.x+(w.b.x-w.a.x)*o.t,cy=w.a.y+(w.b.y-w.a.y)*o.t,half=(o.width||.9)/2;line({x:cx-ux*half,y:cy-uy*half},{x:cx+ux*half,y:cy+uy*half},'OPENINGS');textEntity({x:cx,y:cy+.12},o.type==='door'?'D':'W',140,'OPENINGS')});
rooms.forEach(r=>{const a={x:Math.min(r.a.x,r.b.x),y:Math.min(r.a.y,r.b.y)},b={x:Math.max(r.a.x,r.b.x),y:Math.max(r.a.y,r.b.y)};line(a,{x:b.x,y:a.y},'ROOMS');line({x:b.x,y:a.y},b,'ROOMS');line(b,{x:a.x,y:b.y},'ROOMS');line({x:a.x,y:b.y},a,'ROOMS');textEntity({x:a.x+.1,y:a.y+.15},(r.name||'ROOM')+' '+areaRoom(r).toFixed(2)+' m2',160,'ROOMS')});
dimensions.forEach(d=>{line(d.a,d.b,'DIMENSIONS');const mid={x:(d.a.x+d.b.x)/2,y:(d.a.y+d.b.y)/2};textEntity(mid,len(d).toFixed(2)+' m',140)});
furniture.forEach(f=>{const x=f.x||0,y=f.z||0,w=f.width||1,d=f.depth||.8;const p=[{x:x-w/2,y:y-d/2},{x:x+w/2,y:y-d/2},{x:x+w/2,y:y+d/2},{x:x-w/2,y:y+d/2}];for(let i=0;i<4;i++)line(p[i],p[(i+1)%4],'FURNITURE')});
out.push('0','ENDSEC','0','EOF');
const blob=new Blob([out.join('\r\n')+'\r\n'],{type:'application/dxf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=((($('name')?.value||'ozatroom-project').trim().replace(/[^a-z0-9а-яё_-]+/gi,'-'))||'ozatroom-project')+'.dxf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
$('report').textContent='DXF экспортирован в миллиметрах. Слои: WALLS, OPENINGS, ROOMS, DIMENSIONS, FURNITURE. Открой файл в AutoCAD и при необходимости сохрани как DWG.';
}
